{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/feature-pairs.json
    Four features of FeatureSplit in two columns: a glyph tile beside the title and text, without cards.
    Props (p): features. *}
{var $v_features = ($p['features'] ?? null)}
{capture $c_6}
  {foreach ui_l($v_features) as $v_f}
    {var $v_i = $iterator->counter0}
    {if ui_t(ui_lt($v_i, 4))}
      {capture $c_5}
        {capture $c_1}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_f, ['icon'])), 'Size' => 16]])|noescape}
        {/capture}
        {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'flex size-8 shrink-0 items-center justify-center rounded bg-primary text-primary-foreground'], 'children' => $c_1])|noescape}
        {capture $c_4}
          {capture $c_2}
            {=ui_text(ui_get($v_f, ['title']))}
          {/capture}
          {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_2])|noescape}
          {capture $c_3}
            {=ui_text(ui_get($v_f, ['text']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_3])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Class' => 'min-w-0'], 'children' => $c_4])|noescape}
      {/capture}
      {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'start', 'Attrs' => ui_attrs(['data-testid', 'feature-item'])], 'children' => $c_5])|noescape}
    {/if}
  {/foreach}
{/capture}
{=ui_include('ui/box/box.latte', ['p' => ['Class' => 'grid grid-cols-1 gap-6 sm:grid-cols-2'], 'children' => $c_6])|noescape}
